<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaSecurityFindingService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:issue-subordinate-persona-security-finding')]final class SenateIssueSubordinatePersonaSecurityFindingCommand extends Command{public function __construct(private readonly SubordinatePersonaSecurityFindingService$s){parent::__construct();}protected function configure():void{$this->addArgument('authority-set-id',InputArgument::REQUIRED);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->issue((string)$i->getArgument('authority-set-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln('<info>SECURITY_FINDING_SEALED_PENDING_SEPARATE_RECONCILIATION</info> '.$r['finding_record_id']);return self::SUCCESS;}}

